pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        vm.assume(time > 0);
        vm.assume(ancillaryData.length <= 1000);

        // Record events emitted by the reference contract
        vm.recordLogs();
        c.requestPrice(identifier, time, ancillaryData);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        // Assert that exactly one PriceRequestAdded event was emitted
        uint256 eventCount = 0;
        for (uint256 i = 0; i < logs.length; i++) {
            if (
                logs[i].topics[0] == PriceRequestAdded.selector
            ) {
                eventCount++;
            }
        }
        assertTrue(eventCount == 1);
    }
}

