import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // The modifier onlyOptimisticAsserter checks msg.sender == address(optimisticAsserter).
