        vm.startPrank(address(this));
        c.requestPrice(identifier, time, ancillaryData);
        vm.stopPrank();

        // Read the event logs from the most recent transaction.
        // Since requestPrice emits exactly one event PriceRequestAdded,
        // the emitted data must match the input parameters.
