        // The event is the first (index 0) and only topic after the signature.
        // topics: [sig, indexed identifier]
        // data: abi.encode(time, ancillaryData)
        assertTrue(entries.length == 1, "expected one log");
        (uint256 emittedTime, bytes memory emittedAncillaryData) = abi.decode(entries[0].data, (uint256, bytes));
        assertTrue(emittedTime == time && keccak256(emittedAncillaryData) == keccak256(ancillaryData));
    }
}

