    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        vm.prank(address(c.optimisticAsserter()));
        c.assertionDisputedCallback(assertionId);
        // After the single call, the function should not emit any events.
        // If the buggy version emits an event, it will appear in the recorded logs.
