pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(bytes32 assertionId) public {
        // Ensure the caller is the optimistic asserter (this test contract).
        vm.prank(address(this));

        // Record logs up to the current checkpoint and then call the function.
        vm.recordLogs();
        c.assertionDisputedCallback(assertionId);
        Vm.Log[] memory entries = vm.getRecordedLogs();

        // The general rule: assertionDisputedCallback should never emit a PriceRequestAdded event.
        // The buggy version emits PriceRequestAdded(assertionId, 0, ""), so it will have exactly 1 log.
        // The reference version emits nothing, so entries.length == 0.

        // We assert that no PriceRequestAdded event is emitted.
        // A PriceRequestAdded event has topic0 = keccak256("PriceRequestAdded(bytes32,uint256,bytes)").
        // If the bug is present, entries.length will be 1 and topic0 will match.
        bytes32 expectedTopic = keccak256("PriceRequestAdded(bytes32,uint256,bytes)");
        bool found = false;
        for (uint256 i = 0; i < entries.length; i++) {
            if (entries[i].topics[0] == expectedTopic) {
                found = true;
                break;
            }
        }
        assertTrue(!found, "PriceRequestAdded event was emitted");
    }
}
